"""Generate source-matched release notes without manufacturing runtime success."""
import collections,datetime as dt,json,pathlib
R=pathlib.Path(__file__).resolve().parents[1]
c=json.loads((R/'data/catalog.json').read_text());hubs=('Survival','Minecraft-like worlds');rows=[g for g in c['items'] if any(h in g['hubs'] for h in hubs)]
report={'checkedAt':dt.datetime.now(dt.timezone.utc).isoformat(),'records':len(c['items']),'studyRecords':len(rows),'hubCounts':{h:sum(h in g['hubs'] for g in rows) for h in hubs},'collections':{h:len({g['survivalCollection'] for g in rows if h in g['hubs']}) for h in hubs},'statuses':dict(collections.Counter(g['status'] for g in rows)),'sourceReferences':sum(len(g['storefronts']) for g in rows),'providers':dict(collections.Counter(x['provider'] for g in rows for x in g['storefronts'])),'artwork':sum(bool(g.get('image')) for g in rows),'video':sum(bool(g.get('trailers')) for g in rows),'datasetHash':c['build']['datasetHash']}
(R/'data/survival-study-report.json').write_text(json.dumps(report,indent=2)+'\n')
body='# Games: Survival and Minecraft-like worlds\n\n'
body+=f"This release adds two distinct homes with {len(rows)} unique survival-study entries to the shared library of {len(c['items'])} records. All 1,189 prior identities and all prior genre memberships are preserved.\n\n"
body+='Survival centers on Conan Exiles, ARK and Windrose: shared-world adventures, wilderness, oceans, zombies, space and engineering. Minecraft-like worlds has separate navigation, collections, filters and a distinct visual theme for Minecraft, Terraria, Hytale, Vintage Story, 2D sandboxes, free voxel games and explicitly labelled automation/colony neighbors.\n\n'
body+='Every published study entry has real artwork, supported embedded-video metadata and confirmed distribution links. Official trailers, credited community gameplay and historical development footage are distinguished. Full games, demos, prototypes, Early Access, upcoming releases, archived listings, support memberships and required engines are not conflated.\n\n'
body+='Survival field notes distinguish source-listed solo/co-op, server mentions, modding and terrain systems. Single-player does not guarantee offline access; co-op does not guarantee cross-play or a particular player count. Editorial recommendation strength is separate from Steam or creator-platform ratings and sample sizes.\n\n'
body+='Native wiki: Survival, Survival-Media, Minecraft-Like-Worlds, Minecraft-Like-Media and Survival-Field-Guide. The wiki renders images and links exact videos; the portable HTML has in-page players. Favorites, ratings, notes and saved views retain games.library.v1. No scheduled crawler, generated artwork or viewport culling is introduced.\n\n'
body+='The publication gate retains every earlier unit and browser suite and adds complete new detail/source-panel and primary-image checks. Actual playback probes are distinct from a claim of watching every external video end to end. Confirmed store coverage is not every retailer worldwide. GitHub Pages remains a separate hosting prerequisite.\n'
(R/'docs/RELEASE.md').write_text(body)
(R/'docs/SURVIVAL.md').write_text(body+'\n## Snapshot\n\n```json\n'+json.dumps(report,indent=2)+'\n```\n\n## Updating\n\nRun Enrich survival collection, or Refresh survival discoveries followed by its source collector. Reconciled identities, creator records and edition corrections remain separate canonical layers. Unchanged provider snapshots are reused; unresolved names remain in the research ledger rather than becoming recommendations. Preserve existing game IDs and browser-storage identity.\n')
p=R/'docs/EXECUTION.md';marker='## Survival source checkpoint, October 23, 2026'
if marker not in p.read_text():
 p.write_text(p.read_text()+'\n\n'+marker+'\n\nThe requested Survival and Minecraft-like worlds hubs are integrated. Source checkpoint artifact 12538271115 (SHA-256 73d536a3d65ea3193204a1f1139705061c013446ffdd598330d5d98042202302) retained all reviewed media and source mutations after two integration findings. Repairs normalized the new research-ledger names and extended the existing exact-union assertion to include the new canonical sources, without removing original checks. Source/unit tests precede this coherent checkpoint; complete Chrome validation, actual native Wiki publication, release hashes and Drive synchronization remain required. Next action: the full publication workflow, with scripts/survival_qa.py alongside every previous browser suite. Do not rerun initial source discovery or unmodified failed searches.\n')
print(json.dumps(report,indent=2))
